package com.aiservice.application;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.aiservice.application.port.out.*;import com.aiservice.application.service.*;import com.aiservice.domain.exception.ProviderException;import com.aiservice.domain.model.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import tools.jackson.databind.ObjectMapper;
class AiJobProcessorTest{AiJobRepository jobs=mock(AiJobRepository.class);DocumentRepository docs=mock(DocumentRepository.class);StoragePort storage=mock(StoragePort.class);TextExtractor extractor=mock(TextExtractor.class);AiProvider provider=mock(AiProvider.class);AiResultRepository results=mock(AiResultRepository.class);ProcessedEventRepository inbox=mock(ProcessedEventRepository.class);AiEventPublisher events=mock(AiEventPublisher.class);AiJob job;AiJobProcessor service;UUID event=UUID.randomUUID();@BeforeEach void set(){job=AiJob.pending(UUID.randomUUID(),UUID.randomUUID(),null,JobType.QUESTION_GENERATION,"{}",Instant.now());when(jobs.findById(job.id())).thenReturn(Optional.of(job));when(jobs.save(any())).thenAnswer(i->i.getArgument(0));service=new AiJobProcessor(jobs,docs,storage,extractor,provider,results,inbox,events,new StructuredOutputValidator(new ObjectMapper()),Clock.systemUTC());}
@Test void duplicateMessageSkipped(){when(inbox.exists(event)).thenReturn(true);service.process(event,job.id(),UUID.randomUUID());verifyNoInteractions(provider);}@Test void providerTimeoutIsRetryable(){when(provider.generateQuestions(anyString(),anyString())).thenThrow(new ProviderException("timeout",true,null));assertThrows(ProviderException.class,()->service.process(event,job.id(),null));assertEquals(JobStatus.PROCESSING,job.status());}@Test void providerFailureMarksFailed(){when(provider.generateQuestions(anyString(),anyString())).thenThrow(new ProviderException("bad request",false,null));service.process(event,job.id(),null);assertEquals(JobStatus.FAILED,job.status());verify(events).failed(eq(job),isNull());}@Test void retryExhaustionMarksFailed(){job.start(Instant.now());service.failAfterRetries(event,job.id(),null,"timeout");assertEquals("PROVIDER_RETRY_EXHAUSTED",job.errorCode());}}
